// Builds a scratch dossier state root of synthetic drafts (no real draft, no repository) for a demonstration of the re-render script.
import * as fs from 'node:fs';
import * as path from 'node:path';

const root = process.argv[2];
if (!root) throw new Error('usage: <empty dir>');
const COMMIT = 'c'.repeat(40);
const cite = (id) => ({ id, path: 'src/kestrel.c', startLine: 1, endLine: 3 });
const UNDERSTANDING = ['purpose', 'beneficiary', 'proposition', 'capabilities', 'components', 'choices', 'tradeOffs', 'limits', 'terminology', 'contradictions', 'openQuestions'];
const figure = (id, n) => ({
  id, title: `Figure ${id}`, sectionId: 'core-ideas', kind: 'flow', relationship: 'A chain of steps.',
  nodes: Array.from({ length: n }, (_, i) => ({ id: `${id}-n${i}`, label: `Step ${i}`, epistemic: 'inferred', citations: [cite(`${id}-cn${i}`)] })),
  edges: Array.from({ length: n - 1 }, (_, i) => ({ id: `${id}-e${i}`, from: `${id}-n${i}`, to: `${id}-n${i + 1}`, label: 'then', epistemic: 'inferred', citations: [cite(`${id}-ce${i}`)] })),
  disposition: { kind: 'produced', assetIds: [id] },
});
const draft = (figures) => ({
  schemaVersion: 'polaris-dossier-local-draft-v2', pinnedRevision: COMMIT, sessionId: 'synthetic-1', title: 'Synthetic',
  introduction: { id: 'intro', label: 'inferred', basis: 'source', text: 'A synthetic draft.', citations: [cite('c-intro')], quotations: [] },
  understanding: Object.fromEntries(UNDERSTANDING.map((key) => [key, [{ id: `u-${key}`, label: 'inferred', statement: 'x', scope: 'x', citations: [cite(`u-${key}-c`)] }]])),
  sections: [{ id: 'core-ideas', title: 'Core', paragraphs: [{ id: 'p1', label: 'inferred', basis: 'source', text: 'one two three', citations: [cite('c-p1')], quotations: [], children: [] }], disposition: { kind: 'produced', assetIds: ['core-ideas'] } }],
  diagrams: figures, deepDives: [], unresolved: [],
  discovery: { inspected: [], selected: [], excluded: [], unresolved: [], deferred: [], stoppingReason: 'x' }, clarifications: [], executions: [],
});
const run = path.join(root, `run-${'d'.repeat(32)}`, 'drafts');
fs.mkdirSync(run, { recursive: true });
fs.writeFileSync(path.join(run, 'rev-0.json'), JSON.stringify(draft([figure('a', 3), figure('b', 8)])));
fs.writeFileSync(path.join(run, 'rev-1.json'), JSON.stringify({ ...draft([figure('c', 5)]), title: undefined, sessionId: 7 }));
fs.writeFileSync(path.join(run, 'next.json'), '{}');
fs.mkdirSync(path.join(root, `run-${'d'.repeat(32)}.agents`));
